59. fn book_physical_memory_regions(
60.     physical_memory_regions: LinkedList<TruncatedMemoryRegion<PhysicalAddress>>,
61. ) -> Result<(), Error> {
62.     info!("booking physical memory regions ...");
63. 
64.     // Book physical memory that is not usable.
65.     for region in physical_memory_regions.iter() {
66.         info!("booking: {:?}", region);
67.         frame::alloc_range(region)?;
68.     }
69. 
70.     Ok(())
71. }
72. 
73. fn book_mmio_regions(
74.     mmio_regions: &LinkedList<TruncatedMemoryRegion<VirtualAddress>>,
75. ) -> Result<(), Error> {
76.     info!("booking memory-mapped i/o regions ...");
77. 
78.     // Book memory-mapped I/O regions.
79.     for region in mmio_regions.iter() {
80.         info!("booking: {:?}", region);
81.         let mut start: usize = region.start().into_raw_value();
82.         let end: usize = start + (region.size() - 1);
83.         while start < end {
84.             let mmio_addr: usize = crate::hal::platform::gva_to_gpa(start);
85.             let phys_addr: PageAligned<PhysicalAddress> = PageAligned::from_address(unsafe {
86.                 // MMIO GPAs may legitimately lie outside tracked RAM, so they must not go through
87.                 // the regular physical-address validator here.
88.                 PhysicalAddress::from_mmio_address(VirtualAddress::from_raw_value(mmio_addr))?
89.             })?;
90. 
91.             // Only book frames that the frame allocator actually tracks.
92.             // MMIO regions above RAM (e.g. the LAPIC at 0xFEE0_0000) are not
93.             // covered by the bitmap and must be skipped.
94.             if frame::is_covered(phys_addr) {
95.                 frame::book(phys_addr)?;
96.             }
97.             start += mem::FRAME_SIZE;
98.         }
99.     }
100. 
101.     Ok(())
102. }
