 use crate::{
     hal::mem::{
         Address,
         PageAligned,
         PhysicalAddress,
         TruncatedMemoryRegion,
         VirtualAddress,
     },
     mm::phys::upool::Upool,
 };
 use ::alloc::collections::LinkedList;
 use ::arch::mem;
 use ::bitmap::Bitmap;
 use ::sys::error::Error;
 #[cfg(verus_keep_ghost)]
 use ::vstd::prelude::*;

 // Include specifications.
 #[cfg(verus_keep_ghost)]
 include!("mod.spec.rs");
 #[cfg(verus_keep_ghost)]
 include!("mod.proof.rs");

 //==================================================================================================
 // Exports
