45.     {
46.         &&& self.bitmap.inv()
47.         &&& spec_page_size() > 0
48.         // refcount slice covers all bitmap-managed frames
49.         &&& self.refcount@.len() >= self.bitmap@.num_bits
50.         // bitmap bit set iff refcount > 0
51.         &&& forall|i: int| 0 <= i < self.bitmap@.num_bits ==> (
52.             #[trigger] self.bitmap@.set_bits.contains(i) <==> self.refcount@[i] > 0
53.         )
54.         // bitmap bit clear iff refcount == 0
55.         // NOTE: logically implied by the above when refcount is u8 (>= 0),
56.         // but kept explicit to help the SMT solver without relying on type bounds.
57.         &&& forall|i: int| 0 <= i < self.bitmap@.num_bits ==> (
58.             !self.bitmap@.set_bits.contains(i) <==> self.refcount@[i] == 0
59.         )
60.         // refcount bounded by u8
61.         &&& forall|i: int| 0 <= i < self.bitmap@.num_bits && self.bitmap@.set_bits.contains(i) ==>
62.             0 < self.refcount@[i] <= 255
63.         // Every covered bitmap index yields a non-negative, representable frame address
64.         &&& forall|i: int| 0 <= i < self.bitmap@.num_bits ==> {
65.             &&& frame_addr_of(i) >= 0
66.             &&& frame_addr_of(i) <= usize::MAX as int
